let last = performance.now();
function frame(now) {
  const dt = (now - last) / 1000;   // 경과 시간(초) — 2장
  last = now;
  update(dt);   // 세계를 한 걸음 진행(위치·물리·AI)
  render();     // 현재 상태를 그림
  requestAnimationFrame(frame);   // 다음 프레임
}
requestAnimationFrame(frame);
// rAF: 주사율에 동기(부드러움) + 탭 숨으면 멈춤(절전) — setInterval 보다 나음
// update(진행)와 render(그림)를 나눈다 → 프레임 독립·고정 스텝의 기반

// 나쁨: 프레임이 빠를수록 빨라진다 (좋은 컴퓨터에서 순간이동)
x += 5;

// 좋음: 초당 300px 로 일정 (어느 주사율에서든)
x += 300 * dt;

// dt = 이전 프레임부터의 경과 시간(초)
const dt = (now - last) / 1000;   // rAF 의 now
// 속도·가속·수명·타이머·애니메이션을 프레임 수가 아니라 시간(dt) 기준으로

// 탭 전환/랙 후 dt 가 갑자기 커짐 → 한 프레임에 크게 도약 → 벽 통과(터널링)
function frame(now) {
  let dt = (now - last) / 1000;
  last = now;
  dt = Math.min(dt, 0.05);   // 상한: 한 프레임 최대 이동 제한(표준 방어)
  update(dt);
  render();
  requestAnimationFrame(frame);
}
// 또는: document.visibilitychange 로 탭 숨김 시 일시정지
// 물리·충돌은 작은 스텝을 가정 → 큰 스텝은 그 가정을 깸(4장 고정 스텝)

let acc = 0;
const STEP = 1 / 60;   // 물리 고정 스텝
function frame(now) {
  let dt = (now - last) / 1000; last = now;
  acc += Math.min(dt, 0.25);              // 큰 dt 상한(3장)
  while (acc >= STEP) {
    physics(STEP);   // 물리는 항상 고정 STEP 으로 — 결정적·기계 무관
    acc -= STEP;
  }
  const alpha = acc / STEP;               // 남은 비율
  render(alpha);   // 이전↔현재 물리 상태 사이를 보간 → 부드러움
  requestAnimationFrame(frame);
}
// 고정 스텝(정확·결정성) + 가변 렌더 보간(부드러움)
